// ---------------------------------------------------------------------------
// Full backfill (paginated, resumable)
// ---------------------------------------------------------------------------

/** S5-T1: couch gate must be pass before any --all waterfall mutates routes. */
function assertCouchGateAllowsFullBatch(): void {
  const cmd = 'npx convex run couchVerdict:couchGateStatus'
  process.stdout.write('Checking couchGateStatus before --all...\n')
  try {
    const result = execSync(cmd, { encoding: 'utf-8', stdio: ['ignore', 'pipe', 'pipe'] })
    const gate = JSON.parse(result) as {
      allowed?: boolean
      overallVerdict?: string | null
      reason?: string | null
    }
    if (!gate.allowed) {
      process.stderr.write(
        `COUCH_GATE_BLOCKED: refusing --all before any route mutation.\n` +
          `  overallVerdict=${String(gate.overallVerdict)}\n` +
          `  reason=${gate.reason ?? 'unrecorded or fail'}\n`,
      )
      process.exit(2)
    }
    process.stdout.write(
      `  couchGateStatus allowed (verdict=${String(gate.overallVerdict ?? 'pass')})\n`,
    )
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error)
    process.stderr.write(`COUCH_GATE_BLOCKED: failed to read couchGateStatus: ${msg}\n`)
    process.exit(2)
  }
}

/**
 * S5-T1: couch-gated full waterfall with cost/cursor + coverageReport persistence.
 */
function runFullWaterfallBatch(opts: {
  routeIds: string[]
  maxCost: number | null
  cursor: string | null
  runId: string | null
}): void {
  assertCouchGateAllowsFullBatch()

  const args: Record<string, unknown> = {
    routeIds: opts.routeIds,
    maxCost: opts.maxCost ?? 10,
  }
  if (opts.cursor) args.cursor = opts.cursor
  if (opts.runId) args.runId = opts.runId

  const argsJson = JSON.stringify(args)
  const cmd = `npx convex run waterfallOrchestrator:runFullBatch '${argsJson.replace(/'/g, "'\"'\"'")}'`
  process.stdout.write(`Running full-batch waterfall: ${cmd}\n`)

  try {
    const result = execSync(cmd, { encoding: 'utf-8', stdio: ['ignore', 'pipe', 'pipe'] })
    const report = JSON.parse(result) as {
      runId?: string
      totalCostUSD?: number
      totalCostUsd?: number
      cumulativeCostUSD?: number
      pageCostUSD?: number
      continueCursor?: string | null
      isDone?: boolean
      batchStopReason?: string | null
      coverageReport?: Record<string, unknown>
      processed?: number
      skipped?: number
    }

    // REDHAT-FIX-01: operator transcript must surface real runId/cost/cursor (no isDone+0 stub).
    const transcript = {
      runId: report.runId ?? opts.runId ?? null,
      totalCostUSD: report.totalCostUSD ?? report.totalCostUsd ?? 0,
      cumulativeCostUSD: report.cumulativeCostUSD ?? report.totalCostUSD ?? 0,
      pageCostUSD: report.pageCostUSD ?? report.totalCostUsd ?? report.totalCostUSD ?? 0,
      continueCursor: report.continueCursor ?? null,
      isDone: report.isDone ?? false,
      batchStopReason: report.batchStopReason ?? null,
      processed: report.processed ?? 0,
      skipped: report.skipped ?? 0,
    }

    process.stdout.write('\nFull-batch waterfall report:\n')
    process.stdout.write(`  runId: ${transcript.runId ?? '(none)'}\n`)
    process.stdout.write(`  processed: ${transcript.processed}\n`)
    process.stdout.write(`  skipped: ${transcript.skipped}\n`)
    process.stdout.write(`  totalCostUSD: ${transcript.totalCostUSD}\n`)
    process.stdout.write(`  cumulativeCostUSD: ${transcript.cumulativeCostUSD}\n`)
    process.stdout.write(`  pageCostUSD: ${transcript.pageCostUSD}\n`)
    process.stdout.write(`  batchStopReason: ${transcript.batchStopReason ?? '(none)'}\n`)
    process.stdout.write(`  isDone: ${String(transcript.isDone)}\n`)
    process.stdout.write(`  continueCursor: ${transcript.continueCursor ?? '(none)'}\n`)
    process.stdout.write('\nTRANSCRIPT_JSON ')
    process.stdout.write(JSON.stringify(transcript))
    process.stdout.write('\n')

    const outDir = path.resolve(process.cwd(), '.tmp', 'S5-T1')
    if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true })
    const outPath = path.join(outDir, 'full-batch-report.json')
    fs.writeFileSync(outPath, JSON.stringify({ ...report, transcript }, null, 2))
    process.stdout.write(`\nWrote ${outPath}\n`)

    if (transcript.continueCursor && !transcript.isDone) {
      process.stdout.write(
        `\nTo resume: --all --waterfall --cursor="${transcript.continueCursor}"` +
          (transcript.runId ? ` --run-id=${transcript.runId}` : '') +
          `\n`,
      )
    }
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error)
    process.stderr.write(`Full-batch waterfall failed: ${msg}\n`)
    process.exit(1)
  }
}

async function runFullBackfill(): Promise<void> {
  // S5-T1: even the legacy geometry --all path refuses without couch PASS so the
  // Founder-Operator cannot accidentally full-batch before the Sprint 04 gate.
  assertCouchGateAllowsFullBatch()

  process.stdout.write('Starting full backfill...\n')
  let cursor: string | null = null
  let totalProcessed = 0
  let totalGenerated = 0
  let totalUnresolved = 0
  let totalFailed = 0

  while (true) {
    const report = runBackfill(null, cursor)
    totalProcessed += report.processed
    totalGenerated += report.generated
    totalUnresolved += report.unresolved
    totalFailed += report.failed

    process.stdout.write(
      `Batch: processed=${report.processed} generated=${report.generated} ` +
        `unresolved=${report.unresolved} failed=${report.failed} ` +
        `throttled=${report.throttled}\n`,
    )

    if (report.isDone) {
      process.stdout.write('Backfill complete (all routes processed).\n')
      break
    }

    if (report.throttled) {
      process.stdout.write(`Throttled. Resume with --cursor="${report.continueCursor}"\n`)
      break
    }

    cursor = report.continueCursor

    // Safety: if no routes were processed, we're stuck
    if (report.processed === 0) {
      process.stdout.write('No routes processed in this batch. Stopping.\n')
      break
    }
  }

  process.stdout.write('\nFinal totals:\n')
  process.stdout.write(`  Processed:  ${totalProcessed}\n`)
  process.stdout.write(`  Generated:  ${totalGenerated}\n`)
  process.stdout.write(`  Unresolved: ${totalUnresolved}\n`)
  process.stdout.write(`  Failed:     ${totalFailed}\n`)
  if (totalProcessed > 0) {
    process.stdout.write(
      `  Resolve rate: ${((totalGenerated / totalProcessed) * 100).toFixed(1)}%\n`,
    )
  }
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main(): Promise<void> {
  const { sample, all, cursor, top, maxCost, runId, routeIds, waterfall } = parseArgs(process.argv)

  if (all && waterfall) {
    if (!routeIds || routeIds.length === 0) {
      process.stderr.write(
        '--all --waterfall requires --route-ids=id1,id2,... (explicit batch membership).\n',
      )
      process.exit(1)
    }
    runFullWaterfallBatch({
      routeIds,
      maxCost,
      cursor,
      runId,
    })
    return
  }

  if (top !== null) {
    // --top=N: Process the top-N unprocessed routes by composite_score, WITHOUT the
    // destructive resetSampleRoutes step. This is the mode for backfilling specific
    // high-value routes (e.g. Cherohala Skyway, Wasatch Ridge Traverse) that lack
    // geometry, without disturbing already-processed rows. Requires the
    // by_composite_score index on listForGeometryBackfill (added alongside this mode).
    process.stdout.write(`Running top-${top} backfill (by composite_score, no reset)...\n`)
    const report = runBackfill(top, null)

    process.stdout.write(`\nTop-${top} results:\n`)
    process.stdout.write(`  Processed:  ${report.processed}\n`)
    process.stdout.write(`  Generated:  ${report.generated}\n`)
    process.stdout.write(`  Unresolved: ${report.unresolved}\n`)
    process.stdout.write(`  Failed:     ${report.failed}\n`)
    process.stdout.write(`  Resolve rate: ${(report.resolveRate * 100).toFixed(1)}%\n`)
    process.stdout.write(`  Continue cursor: ${report.continueCursor ?? '(none)'}\n`)
    process.stdout.write(`  Is done: ${report.isDone}\n`)

    // Print a per-route summary so the operator can see Cherohala/Wasatch/etc. results
    process.stdout.write(`\nPer-route:\n`)
    for (const r of report.perRoute) {
      const status = r.status as string
      const coords = r.coordCount != null ? ` (${r.coordCount} coords)` : ''
      const err = r.error != null ? ` [error: ${r.error}]` : ''
      process.stdout.write(`  ${r.routeId} | ${r.name} | ${r.state} | ${status}${coords}${err}\n`)
    }

    // Also write a fidelity-style report (same shape as --sample) for auditability
    const sampleReport = buildSampleReport(report)
    const outDir = path.resolve(process.cwd(), '.tmp', 'DATA-011')
    const outPath = writeSampleReport(sampleReport, outDir)
    process.stdout.write(`\nReport written to: ${outPath}\n`)

